# Built-in benchmark practice problems for DBMS Trigger & RBAC Practice Lab

BENCHMARK_QUESTIONS = [{'id': 'EASY-01', 'title': 'ECA Model Primitives', 'topic': 'Triggers', 'subtopic': 'Formal Trigger Architecture', 'difficulty': 'Easy', 'source': 'ISRO Scientist / Engineer CS', 'question_type': 'conceptual', 'prompt': 'In formal relational database theory, an active database rule is defined by the ECA (Event-Condition-Action) model. Explain what each of the three primitives (Event, Condition, Action) represents in PostgreSQL, and specify which primitive determines whether the trigger body is executed.', 'starter_code': '-- Explain the 3 ECA primitives:\n-- 1. Event:\n-- 2. Condition:\n-- 3. Action:\n-- Which primitive controls conditional execution?', 'solution_key': '1. Event: The database operation (INSERT, UPDATE, DELETE, or TRUNCATE) and timing (BEFORE, AFTER, INSTEAD OF) on a target table that activates the trigger.\n2. Condition: A boolean predicate (e.g., WHEN clause or IF check inside the function) evaluated against transient memory buffers (NEW/OLD). If the condition evaluates to TRUE, the Action is executed; if FALSE, execution is skipped without raising an error.\n3. Action: The procedural code (PL/pgSQL block) executed when the condition holds, performing state adjustments, validation (RAISE EXCEPTION), or auditing.\nThe Condition primitive determines whether the procedural action body executes.', 'ground_truth_explanation': 'The Event invokes the trigger mechanism. The Condition acts as a gatekeeper inspecting in-memory transition records. The Action contains the procedural instructions executed only if the Condition evaluates to true.', 'evaluation_rubric': {'key_concepts': ['Event is DML operation/timing', 'Condition is boolean predicate (WHEN/IF)', 'Action is procedural body', 'Condition controls whether action fires'], 'common_mistakes': ['Confusing Event with Action', 'Stating Event controls condition execution instead of condition gating the action']}, 'hints': ["Hint 1: Think of the Event as 'When something happens', Condition as 'Check if true', and Action as 'Do this'.", 'Hint 2: Look into the SQL WHEN clause to identify which component filters execution.']}, {'id': 'EASY-02', 'title': 'Transition Variables in INSERT Operations', 'topic': 'Triggers', 'subtopic': 'Memory Buffers (NEW vs OLD)', 'difficulty': 'Easy', 'source': 'UGC-NET Computer Science', 'question_type': 'conceptual', 'prompt': 'During an INSERT operation on a PostgreSQL table, what are the states and accessibility of the transition variables NEW and OLD inside a row-level PL/pgSQL trigger? Explain why attempting to read or modify OLD in an INSERT trigger causes an error.', 'starter_code': '-- State of NEW during INSERT:\n-- State of OLD during INSERT:\n-- Reason why OLD is invalid during INSERT:', 'solution_key': 'During an INSERT operation:\n1. NEW: Fully accessible and contains the candidate row proposed for insertion into the relation. In a BEFORE INSERT trigger, NEW fields can be inspected and modified.\n2. OLD: Unassigned / NULL (undefined). In ANSI SQL and PostgreSQL, an INSERT represents the creation of a brand new tuple where no pre-existing disk state exists. Therefore, attempting to read or mutate OLD during an INSERT operation results in a runtime error or evaluates to NULL.', 'ground_truth_explanation': 'Transition variable OLD references the tuple prior to modification. Because an INSERT operation introduces a new row where no prior state exists on the relation heap, OLD is completely undefined.', 'evaluation_rubric': {'key_concepts': ['NEW holds candidate row', 'OLD is NULL/undefined', 'No prior disk tuple exists for INSERT'], 'common_mistakes': ['Claiming OLD contains default column values', 'Assuming OLD is initialized with empty strings']}, 'hints': ['Hint 1: Does a new record have any historical record on disk before it is inserted?', 'Hint 2: In ANSI SQL, OLD represents the pre-state. What is the pre-state of a non-existent row?']}, {'id': 'EASY-03', 'title': 'Basic Role Privileges (GRANT & REVOKE)', 'topic': 'RBAC', 'subtopic': 'Discretionary Access Control', 'difficulty': 'Easy', 'source': 'University Masters Entrance Exam', 'question_type': 'coding', 'prompt': "Write SQL DDL commands to create a banking database role named 'junior_teller' with LOGIN permissions. Grant this role permission to view all records in 'customer_accounts' and insert new transactions into 'daily_transactions', but strictly prohibit this role from updating account balances directly.", 'starter_code': '-- 1. Create role with LOGIN\n-- 2. Grant read access to customer_accounts\n-- 3. Grant insert access to daily_transactions\n-- 4. Ensure direct update on customer_accounts is prohibited', 'solution_key': "CREATE ROLE junior_teller WITH LOGIN PASSWORD 'TellerSecurePass123';\nGRANT SELECT ON customer_accounts TO junior_teller;\nGRANT INSERT ON daily_transactions TO junior_teller;\nREVOKE UPDATE ON customer_accounts FROM junior_teller;", 'ground_truth_explanation': 'PostgreSQL implements Discretionary Access Control (DAC) via SQL standard GRANT and REVOKE syntax. By default, newly created roles have no privileges on user tables. Granting SELECT on customer_accounts allows read-only visibility, while granting INSERT on daily_transactions enables transaction intake. Omitting or explicitly revoking UPDATE maintains balance integrity.', 'evaluation_rubric': {'key_concepts': ['CREATE ROLE with LOGIN', 'GRANT SELECT ON customer_accounts', 'GRANT INSERT ON daily_transactions', 'Prohibit UPDATE on customer_accounts'], 'common_mistakes': ['Using ALL PRIVILEGES', 'Forgetting WITH LOGIN', 'Granting UPDATE on customer_accounts']}, 'hints': ['Hint 1: In PostgreSQL, a role requires WITH LOGIN (or CREATE USER) to authenticate.', 'Hint 2: Explicitly grant only SELECT and INSERT on the respective target relations.']}, {'id': 'EASY-04', 'title': 'BEFORE vs AFTER Trigger Timing', 'topic': 'Triggers', 'subtopic': 'Execution Timing Semantics', 'difficulty': 'Easy', 'source': 'GATE CS 2012', 'question_type': 'conceptual', 'prompt': 'Explain the architectural difference between a BEFORE trigger and an AFTER trigger in PostgreSQL. Specifically: (a) In which trigger type can you modify the values of the NEW record to change what gets committed to disk? (b) In which trigger type does modifying NEW have no effect on the committed row?', 'starter_code': '-- (a) Which trigger timing allows modifying NEW before disk commit?\n-- (b) In which timing does modifying NEW have no effect on the committed row?\n-- Explanation of execution lifecycle:', 'solution_key': "(a) BEFORE trigger: Executes before the prospective row is committed to the relation heap. Modifications made to the NEW pseudo-record (e.g., NEW.status := 'ACTIVE') directly alter the data written to disk upon successful execution.\n(b) AFTER trigger: Executes after the row has already been committed to the relation heap and Write-Ahead Log (WAL). Modifying NEW inside an AFTER trigger has zero effect on the row on disk and is typically forbidden or ignored by the engine. AFTER triggers are intended for post-commit actions such as cascading updates, external notifications, and audit logging.", 'ground_truth_explanation': 'BEFORE triggers intercept candidate tuples in transient memory before heap allocation, allowing transformation and constraint validation. AFTER triggers fire after heap insertion, meaning the candidate row has already been persisted.', 'evaluation_rubric': {'key_concepts': ['BEFORE allows modifying NEW', 'AFTER cannot modify committed row', 'AFTER is for secondary cascading/audit effects'], 'common_mistakes': ['Assuming AFTER triggers can sanitize input data', 'Confusing statement rollback with row mutation']}, 'hints': ['Hint 1: Can you alter a physical letter after you have already mailed it?', 'Hint 2: Look at when Write-Ahead Logging (WAL) occurs relative to trigger execution.']}, {'id': 'EASY-05', 'title': 'Row-Level vs Statement-Level Granularity', 'topic': 'Triggers', 'subtopic': 'Trigger Granularity', 'difficulty': 'Easy', 'source': 'BITS HD Masters Entrance', 'question_type': 'conceptual', 'prompt': "Consider an UPDATE statement that modifies 100 rows in a single query: 'UPDATE customer_accounts SET balance = balance + 10 WHERE account_type = 'SAVINGS';'. (a) How many times will a 'FOR EACH ROW' trigger execute? (b) How many times will a 'FOR EACH STATEMENT' trigger execute? (c) Are transition variables NEW and OLD accessible in a statement-level trigger in standard PL/pgSQL?", 'starter_code': '-- (a) Number of executions for FOR EACH ROW:\n-- (b) Number of executions for FOR EACH STATEMENT:\n-- (c) Accessibility of NEW and OLD in statement-level triggers:', 'solution_key': "(a) A 'FOR EACH ROW' trigger will execute exactly 100 times (once for each modified row).\n(b) A 'FOR EACH STATEMENT' trigger will execute exactly 1 time for the entire SQL statement, regardless of how many rows are modified.\n(c) In standard PostgreSQL PL/pgSQL, the single-row transition variables NEW and OLD are NOT accessible in statement-level triggers (they are NULL/undefined) because a statement affects multiple rows simultaneously. (Transition tables via REFERENCING NEW TABLE AS are used for set-based inspection instead).", 'ground_truth_explanation': 'Row-level triggers fire iteratively for each affected tuple and provide row-by-row NEW/OLD inspection. Statement-level triggers fire once per SQL command for coarse-grained auditing, where individual row pseudo-records do not exist.', 'evaluation_rubric': {'key_concepts': ['FOR EACH ROW executes 100 times', 'FOR EACH STATEMENT executes 1 time', 'NEW/OLD are not accessible in statement triggers'], 'common_mistakes': ['Saying statement triggers execute 0 times if 100 rows match', 'Claiming NEW holds an array in statement triggers']}, 'hints': ['Hint 1: Count the individual tuples versus the number of SQL command statements executed.', "Hint 2: How can a single variable 'NEW' represent 100 different rows at the same time?"]}, {'id': 'MED-01', 'title': 'Cascading Triggers and Rollback Boundaries', 'topic': 'Triggers', 'subtopic': 'ACID Atomicity & Cascades', 'difficulty': 'Medium', 'source': 'GATE CS 2018', 'question_type': 'conceptual', 'prompt': 'In PostgreSQL, Trigger T1 fires BEFORE INSERT on Table A and executes an UPDATE on Table B. This UPDATE on Table B fires Trigger T2 (AFTER UPDATE on Table B), which raises an EXCEPTION due to a constraint failure. Explain the transaction outcome: (a) Does Table A contain the inserted row? (b) Does Table B retain the updated value? (c) Explain the ACID atomicity boundary across cascading triggers.', 'starter_code': '-- (a) Status of Table A insertion:\n-- (b) Status of Table B update:\n-- (c) ACID Atomicity explanation across cascade:', 'solution_key': '(a) No, Table A does NOT contain the inserted row.\n(b) No, Table B does NOT retain the updated value.\n(c) In PostgreSQL and relational database standards, an SQL statement and all procedural triggers cascading from it execute inside a single atomic transaction boundary. When Trigger T2 executes RAISE EXCEPTION, an immediate transaction ROLLBACK is initiated. All changes staged in volatile memory or heap pages across Table A, Table B, and any intermediate triggers are completely discarded. Zero partial writes occur, preserving the ACID Atomicity guarantee.', 'ground_truth_explanation': 'Cascaded triggers do not spawn independent autonomous subtransactions. The entire chain shares the parent transaction context. An unhandled exception at any depth rolls back the entire call stack.', 'evaluation_rubric': {'key_concepts': ['Table A rolled back', 'Table B rolled back', 'All triggers share single transaction', 'RAISE EXCEPTION triggers full ROLLBACK'], 'common_mistakes': ['Thinking Table A succeeds because T1 finished before T2 failed', 'Assuming triggers commit independently']}, 'hints': ["Hint 1: Recall the 'A' in ACID properties: Atomicity (All or Nothing).", "Hint 2: Do triggers run in separate transactions by default or within the caller's transaction?"]}, {'id': 'MED-02', 'title': 'Salary Reduction Guard via BEFORE Trigger', 'topic': 'Triggers', 'subtopic': 'PL/pgSQL Trigger Functions', 'difficulty': 'Medium', 'source': 'GATE CS 2021', 'question_type': 'coding', 'prompt': "Write a complete PostgreSQL PL/pgSQL trigger function named 'check_salary_reduction()' and its corresponding CREATE TRIGGER statement on relation 'employee(emp_id, emp_name, salary, department)'. The trigger must prevent any UPDATE that decreases an employee's salary. If a salary decrease is attempted, it must abort with an error code and message 'SALARY_DECREASE_NOT_ALLOWED'. Otherwise, it should permit the update.", 'starter_code': '-- 1. Create or replace function check_salary_reduction()\n-- 2. Validate salary modification\n-- 3. Create trigger binding', 'solution_key': "CREATE OR REPLACE FUNCTION check_salary_reduction()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.salary < OLD.salary THEN\n        RAISE EXCEPTION 'SALARY_DECREASE_NOT_ALLOWED: Proposed salary % is less than current salary %',\n            NEW.salary, OLD.salary;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_salary_reduction_guard\nBEFORE UPDATE OF salary ON employee\nFOR EACH ROW\nEXECUTE FUNCTION check_salary_reduction();", 'ground_truth_explanation': 'A BEFORE UPDATE trigger is essential to intercept the proposed row before persistence. Comparing NEW.salary with OLD.salary detects decreases. RAISE EXCEPTION halts execution and aborts the transaction. Returning NEW is required for successful updates to proceed.', 'evaluation_rubric': {'key_concepts': ['BEFORE UPDATE timing', 'Comparing NEW.salary < OLD.salary', 'RAISE EXCEPTION with error message', 'RETURN NEW', 'FOR EACH ROW'], 'common_mistakes': ['Using AFTER UPDATE', 'Returning NULL on valid update', 'Comparing OLD.salary < NEW.salary', 'Omitting RETURN NEW']}, 'hints': ['Hint 1: Use BEFORE UPDATE so you can validate prior to disk commitment.', 'Hint 2: What must a BEFORE trigger return when the check passes so the engine continues writing the row?']}, {'id': 'MED-03', 'title': 'SECURITY DEFINER vs SECURITY INVOKER', 'topic': 'Hybrid Security', 'subtopic': 'Privilege Elevation & Auditing', 'difficulty': 'Medium', 'source': 'IIIT-H PGEE Masters Entrance', 'question_type': 'conceptual', 'prompt': "In an enterprise banking database, normal tellers have no direct INSERT or UPDATE privileges on the 'audit_log' table. However, an AFTER UPDATE trigger on 'customer_accounts' must record an audit entry into 'audit_log' whenever a teller updates an account. (a) Should the trigger function be declared as SECURITY INVOKER or SECURITY DEFINER? (b) Explain the difference between these execution modes and why the selected mode solves this security dilemma.", 'starter_code': '-- (a) Selected security mode (SECURITY INVOKER or SECURITY DEFINER):\n-- (b) Explanation of execution modes and reason for choice:', 'solution_key': "(a) The trigger function must be declared as SECURITY DEFINER.\n(b) By default, PostgreSQL functions execute as SECURITY INVOKER, meaning they execute with the permissions of the user calling the query (the teller). If SECURITY INVOKER is used, the trigger will fail with error 42501 (insufficient_privilege) because the teller lacks write grants on 'audit_log'.\nDeclaring the function as SECURITY DEFINER instructs PostgreSQL to temporarily elevate execution privileges to that of the user who owns the function (e.g., 'postgres' / DBA). This allows the function to silently append audit entries to 'audit_log' on behalf of the teller, while keeping 'audit_log' completely protected from direct unauthorized modifications by tellers.", 'ground_truth_explanation': 'SECURITY DEFINER implements controlled privilege escalation akin to setuid in Unix. It enables untrusted roles to execute privileged schema actions strictly through audited procedural pathways without granting raw table privileges.', 'evaluation_rubric': {'key_concepts': ['SECURITY DEFINER selected', 'SECURITY INVOKER uses caller privileges', 'SECURITY DEFINER elevates to owner/DBA privileges', 'Solves privilege dilemma for audit logging'], 'common_mistakes': ['Recommending granting direct INSERT privilege on audit_log to tellers', 'Claiming triggers always run as superuser']}, 'hints': ['Hint 1: In Linux, setuid binaries run as root even when launched by a standard user. What is the SQL function equivalent?', 'Hint 2: If a teller has no rights on audit_log, who should the function pretend to be?']}, {'id': 'MED-04', 'title': 'Statement-Level Trigger on Zero Rows Mutated', 'topic': 'Triggers', 'subtopic': 'Execution Edge Cases', 'difficulty': 'Medium', 'source': 'GATE CS 2015', 'question_type': 'conceptual', 'prompt': "Consider relation 'students(id, marks)'. A database administrator creates: (1) Trigger T_row: AFTER UPDATE FOR EACH ROW on students; (2) Trigger T_stmt: AFTER UPDATE FOR EACH STATEMENT on students. A user executes: 'UPDATE students SET marks = marks + 5 WHERE marks > 100;'. Suppose no student currently has marks > 100. (a) How many times does T_row fire? (b) How many times does T_stmt fire? Explain the standard relational reasoning.", 'starter_code': '-- (a) Number of times T_row fires:\n-- (b) Number of times T_stmt fires:\n-- Explanation of engine behavior:', 'solution_key': '(a) T_row fires 0 times.\n(b) T_stmt fires exactly 1 time.\nExplanation: A row-level trigger (FOR EACH ROW) fires dynamically for each tuple that matches the WHERE clause and undergoes mutation. Since 0 rows qualified, the row trigger loop is never entered.\nIn contrast, a statement-level trigger (FOR EACH STATEMENT) is tied directly to the execution of the SQL DML statement itself, not to the resulting row count. Even if an UPDATE statement modifies zero rows, the statement was successfully parsed, planned, and dispatched by the engine, so statement-level BEFORE and AFTER triggers fire once.', 'ground_truth_explanation': 'Row triggers are data-driven; statement triggers are command-driven. A valid SQL command that processes an empty result set still completes a statement lifecycle.', 'evaluation_rubric': {'key_concepts': ['T_row fires 0 times', 'T_stmt fires 1 time', 'Statement trigger fires regardless of row match count'], 'common_mistakes': ['Assuming T_stmt also fires 0 times', 'Confusing syntax failure with zero row match']}, 'hints': ['Hint 1: Distinguish between the SQL command itself versus the rows affected by the command.', 'Hint 2: Does an UPDATE command execute if no rows match the WHERE clause?']}, {'id': 'MED-05', 'title': 'Column-Level RBAC and Views', 'topic': 'RBAC', 'subtopic': 'Fine-Grained Authorization', 'difficulty': 'Medium', 'source': 'ISRO Scientist SC', 'question_type': 'coding', 'prompt': "Given a table 'customer_profiles(profile_id, full_name, phone_number, national_id, kyc_status)'. (a) Write SQL to grant 'support_staff' the ability to view only 'profile_id', 'full_name', and 'phone_number' while hiding 'national_id' and 'kyc_status'. (b) Write SQL to allow 'support_staff' to UPDATE only 'phone_number'. (c) Explain whether column-level grants or views are preferred for security auditing.", 'starter_code': '-- (a) Grant read access to specific columns\n-- (b) Grant update access to phone_number only\n-- (c) Architectural explanation:', 'solution_key': "-- (a) Column-level SELECT grant\nGRANT SELECT (profile_id, full_name, phone_number) ON customer_profiles TO support_staff;\n\n-- (b) Column-level UPDATE grant\nGRANT UPDATE (phone_number) ON customer_profiles TO support_staff;\n\n-- (c) Architectural Comparison:\nColumn-level GRANT enforces permissions directly in PostgreSQL's system catalog (information_schema.column_privileges), preventing leakage across direct queries. However, creating a secured VIEW (e.g., customer_contact_view) and granting permissions on the view is often preferred in enterprise design because it simplifies schema evolution, simplifies audit tracking in pg_stat_activity, and prevents accidental catalog lock contention.", 'ground_truth_explanation': 'PostgreSQL supports column-level privilege granularity directly in the catalog. Granular column grants protect PII (national_id) and compliance statuses (kyc_status) from operational support roles.', 'evaluation_rubric': {'key_concepts': ['GRANT SELECT (cols) ON table TO role', 'GRANT UPDATE (col) ON table TO role', 'Comparison with secured VIEWs'], 'common_mistakes': ['Granting SELECT on entire table', 'Omitting column list in parentheses']}, 'hints': ['Hint 1: In SQL, specify the column list in parentheses immediately after the privilege keyword.', 'Hint 2: How can views provide an abstraction barrier over raw table schemas?']}, {'id': 'HARD-01', 'title': 'Mutating Table & Infinite Trigger Recursion Guard', 'topic': 'Triggers', 'subtopic': 'Recursive Triggers & Re-entrancy', 'difficulty': 'Hard', 'source': 'Stanford CS145 / CMU 15-445', 'question_type': 'coding', 'prompt': "In an accounting ledger, whenever an account balance is updated in 'accounts(account_id, balance, update_count)', an AFTER UPDATE trigger must increment 'update_count = update_count + 1'. However, updating the row inside an AFTER UPDATE trigger risks an infinite recursive trigger loop (Trigger -> Update -> Trigger -> Update...). Write a PL/pgSQL solution that safely increments 'update_count' without infinite recursion, or explain how converting this to a BEFORE trigger solves the mutating re-entrancy issue.", 'starter_code': '-- Provide either a BEFORE trigger approach or recursion-safe AFTER trigger approach:\n-- Explain how PostgreSQL prevents stack overflow / infinite recursion:', 'solution_key': "-- Solution: Architectural Conversion to BEFORE UPDATE Trigger\nCREATE OR REPLACE FUNCTION increment_account_update_count()\nRETURNS TRIGGER AS $$\nBEGIN\n    -- Prevent infinite recursion by directly mutating candidate tuple in memory\n    NEW.update_count := OLD.update_count + 1;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_increment_update_count\nBEFORE UPDATE OF balance ON accounts\nFOR EACH ROW\nEXECUTE FUNCTION increment_account_update_count();\n\n-- Relational Explanation:\nIn an AFTER trigger, modifying the table requires issuing an explicit 'UPDATE accounts ...' query, which re-invokes the UPDATE trigger, leading to infinite recursion until PostgreSQL hits 'max_stack_depth' and crashes.\nBy converting this to a BEFORE UPDATE trigger, we modify the transient in-memory record (NEW.update_count := OLD.update_count + 1) directly before the row is persisted. No secondary UPDATE query is dispatched, completely eliminating re-entrancy and recursive loops.", 'ground_truth_explanation': 'Mutating table recursion occurs when an active trigger issues a DML statement against its own target relation. Using a BEFORE trigger allows in-place mutation of the NEW buffer without firing secondary DML events.', 'evaluation_rubric': {'key_concepts': ['NEW.update_count := OLD.update_count + 1', 'BEFORE UPDATE eliminates recursion', 'AFTER trigger requires explicit DML causing loop', 'Zero secondary query dispatched'], 'common_mistakes': ['Issuing an UPDATE statement inside a BEFORE trigger', 'Failing to explain max_stack_depth recursion risk']}, 'hints': ['Hint 1: Why issue an UPDATE statement when you already have the candidate row in memory?', 'Hint 2: Can a BEFORE trigger modify column values before they are committed?']}, {'id': 'HARD-02', 'title': 'Anti-Loan Stacking Linear State Machine', 'topic': 'Triggers', 'subtopic': 'State Machines & Concurrency', 'difficulty': 'Hard', 'source': 'Core Banking Architecture / CMU 15-445', 'question_type': 'coding', 'prompt': "Write a complete PostgreSQL trigger function 'enforce_loan_state_machine()' on 'loan_applications(app_id, profile_id, amount, status)'. The system enforces a strict linear workflow: SUBMITTED -> UNDERWRITE -> APPROVED or REJECTED. The trigger must: (1) Block any attempt to skip UNDERWRITE (e.g. SUBMITTED directly to APPROVED); (2) Block any attempt to revert backwards (e.g. UNDERWRITE back to SUBMITTED); (3) Block any mutation if the loan is already in terminal state APPROVED or REJECTED. Raise descriptive exceptions for violations.", 'starter_code': '-- 1. Trigger function enforce_loan_state_machine()\n-- 2. State transition rules:\n--    SUBMITTED -> UNDERWRITE\n--    UNDERWRITE -> APPROVED or REJECTED\n--    Terminal states are immutable\n-- 3. Trigger declaration', 'solution_key': "CREATE OR REPLACE FUNCTION enforce_loan_state_machine()\nRETURNS TRIGGER AS $$\nBEGIN\n    -- Rule 3: Terminal state immutability\n    IF OLD.status IN ('APPROVED', 'REJECTED') THEN\n        RAISE EXCEPTION 'TERMINAL_STATE_LOCKED: Cannot modify application in % state', OLD.status;\n    END IF;\n\n    -- Rule 1 & 2: Linear state machine progression\n    IF OLD.status = 'SUBMITTED' AND NEW.status != 'UNDERWRITE' THEN\n        RAISE EXCEPTION 'ILLEGAL_TRANSITION: Applications in SUBMITTED state can only transition to UNDERWRITE (attempted: %)', NEW.status;\n    ELSIF OLD.status = 'UNDERWRITE' AND NEW.status NOT IN ('APPROVED', 'REJECTED') THEN\n        RAISE EXCEPTION 'ILLEGAL_TRANSITION: Underwrite reviews can only transition to APPROVED or REJECTED (attempted: %)', NEW.status;\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_loan_state_machine\nBEFORE UPDATE OF status ON loan_applications\nFOR EACH ROW\nEXECUTE FUNCTION enforce_loan_state_machine();", 'ground_truth_explanation': 'State machines implemented at the database tier protect data consistency across all applications accessing the database. By enforcing transition guards in a BEFORE UPDATE trigger, unauthorized state skips and reversions are prevented regardless of the application framework.', 'evaluation_rubric': {'key_concepts': ["Terminal check on OLD.status IN ('APPROVED', 'REJECTED')", 'SUBMITTED -> UNDERWRITE validation', 'UNDERWRITE -> APPROVED/REJECTED validation', 'BEFORE UPDATE OF status', 'RETURN NEW'], 'common_mistakes': ['Using AFTER UPDATE', 'Allowing updates on terminal states', 'Allowing backward transition to SUBMITTED']}, 'hints': ['Hint 1: Check OLD.status first to see if the record has already reached a finalized terminal state.', 'Hint 2: Enforce valid next states based on OLD.status and compare against NEW.status.']}, {'id': 'HARD-03', 'title': 'Privilege Revocation Cascades (CASCADE vs RESTRICT)', 'topic': 'RBAC', 'subtopic': 'Authorization Grant Graphs', 'difficulty': 'Hard', 'source': 'GATE CS Advanced 2023', 'question_type': 'conceptual', 'prompt': "User A (table owner) grants SELECT WITH GRANT OPTION on table T to User B. User B grants SELECT to User C. User C grants SELECT to User D. User A later executes: 'REVOKE SELECT ON T FROM User B CASCADE;'. (a) What happens to the SELECT privilege of User C and User D? (b) What would happen if User A executed 'REVOKE SELECT ON T FROM User B RESTRICT;' instead? (c) Explain the authorization grant graph traversal algorithm used by the DBMS.", 'starter_code': '-- (a) Status of User C and User D privileges under CASCADE:\n-- (b) Outcome under RESTRICT:\n-- (c) Grant graph traversal explanation:', 'solution_key': "(a) Under CASCADE, the SELECT privileges of User C and User D are both automatically REVOKED. In the SQL authorization grant graph, C received the privilege from B, and D received it from C. When B's grant is revoked with CASCADE, all dependent permissions downstream in the grant graph that depend solely on B are recursively revoked.\n(b) Under RESTRICT, the REVOKE command fails with an ERROR and NO privileges are revoked. RESTRICT mandates that if any dependent downstream privileges exist (such as B's grant to C), the revocation must be aborted to prevent unintended cascading loss.\n(c) The DBMS maintains a directed authorization grant graph where nodes are users and directed edges represent grants. When revoking, the DBMS computes a reachability traversal from the schema owner. If a node has no remaining path from an independent granter, its privilege node is deleted under CASCADE.", 'ground_truth_explanation': 'SQL-92 Discretionary Access Control specifies grant graph semantics. CASCADE traverses all descendants in the directed acyclic graph (DAG) rooted at the target grant. RESTRICT enforces referential integrity on the grant graph.', 'evaluation_rubric': {'key_concepts': ['CASCADE revokes C and D', 'RESTRICT aborts with error', 'Directed authorization grant graph / DAG reachability'], 'common_mistakes': ['Thinking RESTRICT only revokes B and leaves C and D orphaned', 'Assuming C and D keep privileges under CASCADE']}, 'hints': ['Hint 1: Draw a directed graph: A -> B -> C -> D. What happens if edge A->B is cut with CASCADE?', 'Hint 2: What is the purpose of RESTRICT in foreign keys and how does it parallel REVOKE?']}, {'id': 'HARD-04', 'title': 'INSTEAD OF Triggers on Non-Updatable Views', 'topic': 'Triggers', 'subtopic': 'View Updatability & Abstraction', 'difficulty': 'Hard', 'source': 'UC Berkeley CS186', 'question_type': 'coding', 'prompt': "Given relations 'accounts(account_id, profile_id, balance)' and 'profiles(profile_id, full_name, email)'. A view 'customer_summary_view' joins both tables: 'SELECT a.account_id, p.full_name, a.balance FROM accounts a JOIN profiles p ON a.profile_id = p.profile_id;'. By default, multi-table join views are not directly updatable in SQL. Write an INSTEAD OF UPDATE trigger function in PL/pgSQL that allows updating 'full_name' (delegated to 'profiles') and 'balance' (delegated to 'accounts') through the view.", 'starter_code': '-- 1. Trigger function for view update delegation\n-- 2. Dispatch updates to accounts and profiles\n-- 3. CREATE TRIGGER ... INSTEAD OF UPDATE ON customer_summary_view', 'solution_key': 'CREATE OR REPLACE FUNCTION update_customer_summary_view()\nRETURNS TRIGGER AS $$\nBEGIN\n    -- Update the underlying accounts relation\n    IF NEW.balance != OLD.balance THEN\n        UPDATE accounts \n        SET balance = NEW.balance \n        WHERE account_id = OLD.account_id;\n    END IF;\n\n    -- Update the underlying profiles relation\n    IF NEW.full_name != OLD.full_name THEN\n        UPDATE profiles \n        SET full_name = NEW.full_name \n        WHERE profile_id = (\n            SELECT profile_id FROM accounts WHERE account_id = OLD.account_id\n        );\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_instead_of_update_summary\nINSTEAD OF UPDATE ON customer_summary_view\nFOR EACH ROW\nEXECUTE FUNCTION update_customer_summary_view();', 'ground_truth_explanation': 'Complex views with multi-table joins cannot be mapped unambiguously to underlying relations by the query optimizer. INSTEAD OF triggers intercept DML on the view and procedurally route updates to individual normalized base tables.', 'evaluation_rubric': {'key_concepts': ['INSTEAD OF UPDATE ON view', 'Routing balance to accounts table', 'Routing full_name to profiles table', 'RETURN NEW'], 'common_mistakes': ['Using BEFORE or AFTER trigger on a view (invalid in PostgreSQL)', 'Directly updating the view inside the trigger body causing an infinite loop']}, 'hints': ['Hint 1: Can you use a BEFORE or AFTER trigger on a view in PostgreSQL, or is INSTEAD OF required?', 'Hint 2: How do you identify which profile_id corresponds to OLD.account_id?']}, {'id': 'HARD-05', 'title': 'Tamper-Proof Ledger via Append-Only Triggers', 'topic': 'Hybrid Security', 'subtopic': 'Immutable Relational Audit Trails', 'difficulty': 'Hard', 'source': 'Foreign Masters CS / Financial Security', 'question_type': 'coding', 'prompt': "Design an immutable audit logging architecture for relation 'audit_log(log_id, actor, action, payload, logged_at)'. Implement a PL/pgSQL trigger 'protect_audit_integrity()' that makes 'audit_log' completely tamper-proof: (1) Any attempt to UPDATE an existing audit record is immediately rejected with exception 'AUDIT_LOG_IMMUTABLE'; (2) Any attempt to DELETE an existing audit record is immediately rejected with exception 'AUDIT_LOG_APPEND_ONLY'; (3) Explain why trigger-based enforcement provides defense-in-depth even if a user bypasses the UI.", 'starter_code': '-- 1. Trigger function protect_audit_integrity()\n-- 2. Reject UPDATE and DELETE operations\n-- 3. Bind trigger to audit_log\n-- 4. Defense-in-depth explanation:', 'solution_key': "CREATE OR REPLACE FUNCTION protect_audit_integrity()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF TG_OP = 'UPDATE' THEN\n        RAISE EXCEPTION 'AUDIT_LOG_IMMUTABLE: Modification of forensic audit records is prohibited.';\n    ELSIF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION 'AUDIT_LOG_APPEND_ONLY: Deletion of forensic audit records is strictly prohibited.';\n    END IF;\n    RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_audit_immutability\nBEFORE UPDATE OR DELETE ON audit_log\nFOR EACH ROW\nEXECUTE FUNCTION protect_audit_integrity();\n\n-- Defense-in-Depth Explanation:\nApplication-level controls (such as disabling Edit/Delete buttons in web UIs) fail if an attacker obtains database credentials, uses SQL injection, or connects via psql. By embedding this rule inside a BEFORE UPDATE OR DELETE trigger directly within the PostgreSQL kernel, immutability is guaranteed at the storage engine level, regardless of the client tool used.", 'ground_truth_explanation': 'TG_OP identifies the executing DML operation. Intercepting UPDATE and DELETE in a BEFORE trigger and raising an exception guarantees append-only immutability at the physical database layer.', 'evaluation_rubric': {'key_concepts': ["TG_OP = 'UPDATE' check", "TG_OP = 'DELETE' check", 'RAISE EXCEPTION', 'BEFORE UPDATE OR DELETE ON audit_log', 'Kernel-level defense-in-depth explanation'], 'common_mistakes': ['Using AFTER trigger allowing partial execution', 'Forgetting to check both UPDATE and DELETE']}, 'hints': ['Hint 1: In PostgreSQL PL/pgSQL, which special variable indicates the DML operation (INSERT, UPDATE, DELETE)?', 'Hint 2: Where should immutability be enforced if an attacker connects directly via psql command-line?']}, {'id': 'EASY-06', 'title': 'Trigger Execution on TRUNCATE Operations', 'topic': 'Triggers', 'subtopic': 'Statement-Level DDL & Bulk Operations', 'difficulty': 'Easy', 'source': 'ISRO Scientist / Engineer CS', 'question_type': 'conceptual', 'prompt': 'In PostgreSQL, how do triggers behave when a TRUNCATE TABLE command is executed? Specifically: (a) Can a FOR EACH ROW trigger fire during TRUNCATE? (b) Can a FOR EACH STATEMENT trigger fire during TRUNCATE? (c) Are NEW or OLD transition records available during TRUNCATE?', 'starter_code': '-- (a) Behavior of FOR EACH ROW triggers during TRUNCATE:\n-- (b) Behavior of FOR EACH STATEMENT triggers during TRUNCATE:\n-- (c) Availability of transition variables (NEW/OLD):', 'solution_key': "(a) No, FOR EACH ROW triggers CANNOT fire on TRUNCATE. TRUNCATE is a high-speed bulk DDL operation that empties the relation heap by resetting table storage pointers rather than scanning and deleting individual tuples.\n(b) Yes, a FOR EACH STATEMENT trigger can fire on TRUNCATE if explicitly defined with 'BEFORE TRUNCATE' or 'AFTER TRUNCATE'.\n(c) Neither NEW nor OLD transition records exist or are accessible during a TRUNCATE trigger because individual rows are never materialized or passed through the executor buffer.", 'ground_truth_explanation': 'TRUNCATE bypasses individual row deletion mechanisms to achieve high throughput. Therefore, row-level triggers and transition pseudo-records are completely bypassed; only statement-level triggers defined on TRUNCATE fire.', 'evaluation_rubric': {'key_concepts': ['Row triggers do not fire on TRUNCATE', 'Statement triggers can fire on TRUNCATE', 'NEW and OLD are not available on TRUNCATE'], 'common_mistakes': ['Assuming row triggers fire for every truncated row', 'Claiming OLD contains deleted tuples']}, 'hints': ['Hint 1: Does TRUNCATE scan rows individually like DELETE does?', 'Hint 2: In PostgreSQL documentation, which trigger granularity supports the TRUNCATE event?']}, {'id': 'EASY-07', 'title': 'Discretionary (DAC) vs Mandatory Access Control (MAC)', 'topic': 'RBAC', 'subtopic': 'Access Control Paradigms', 'difficulty': 'Easy', 'source': 'UGC-NET Computer Science', 'question_type': 'conceptual', 'prompt': 'Compare Discretionary Access Control (DAC) and Mandatory Access Control (MAC) in relational database security. Identify which model standard PostgreSQL GRANT/REVOKE commands implement, and explain who has the authority to grant permissions under DAC.', 'starter_code': '-- DAC vs MAC Comparison:\n-- Which model does PostgreSQL GRANT/REVOKE implement?\n-- Who can grant permissions in DAC?', 'solution_key': '1. Discretionary Access Control (DAC): In DAC, access rights to an object are determined by the owner of the object. The owner (or someone granted permissions WITH GRANT OPTION) has full discretion to pass privileges to other users.\n2. Mandatory Access Control (MAC): In MAC, access rights are determined centrally by strict system-wide security clearances and classification labels (e.g., Top Secret, Secret, Confidential). Users cannot pass permissions at their own discretion.\nPostgreSQL standard GRANT and REVOKE commands implement DAC. In DAC, the relation creator (owner) or a superuser holds the primary authority to grant permissions.', 'ground_truth_explanation': 'DAC is based on object ownership and discretionary delegation via GRANT/REVOKE. MAC relies on multi-level security classifications enforced by the kernel regardless of user preferences.', 'evaluation_rubric': {'key_concepts': ['DAC determined by object owner', 'MAC determined by system-wide security labels', 'PostgreSQL implements DAC', 'Owner or superuser grants permissions in DAC'], 'common_mistakes': ['Claiming PostgreSQL implements MAC by default', 'Confusing DAC with Bell-LaPadula clearance levels']}, 'hints': ['Hint 1: If you create a table in PostgreSQL, can you decide who reads it?', 'Hint 2: In military databases, can an author share Top Secret documents with an unclassified user at will?']}, {'id': 'EASY-08', 'title': 'Role Creation and Authentication Flags', 'topic': 'RBAC', 'subtopic': 'PostgreSQL Role Architecture', 'difficulty': 'Easy', 'source': 'PostgreSQL Certified Associate', 'question_type': 'coding', 'prompt': "Write SQL statements to create a security group role named 'auditors' without login capability, and an individual user role named 'alice' with password 'SecPass#2026' that can log in and is a member of 'auditors'.", 'starter_code': "-- 1. Create group role 'auditors'\n-- 2. Create user 'alice' with login and password\n-- 3. Assign alice to auditors group", 'solution_key': "CREATE ROLE auditors NOLOGIN;\nCREATE ROLE alice WITH LOGIN PASSWORD 'SecPass#2026' IN ROLE auditors;", 'ground_truth_explanation': "In PostgreSQL, users and groups are unified into the 'ROLE' abstraction. Setting NOLOGIN designates a role as a group or privilege container. Setting WITH LOGIN allows a role to establish database sessions. The IN ROLE clause grants immediate group membership.", 'evaluation_rubric': {'key_concepts': ['CREATE ROLE auditors NOLOGIN', 'CREATE ROLE alice WITH LOGIN', 'PASSWORD assignment', 'IN ROLE auditors or GRANT auditors TO alice'], 'common_mistakes': ['Using deprecated CREATE USER without recognizing it is an alias for CREATE ROLE WITH LOGIN', 'Omitting NOLOGIN for group role']}, 'hints': ['Hint 1: In PostgreSQL, what flag differentiates a group role from an authenticating user account?', 'Hint 2: You can assign group membership either inline with IN ROLE or via GRANT role_name TO user.']}, {'id': 'EASY-09', 'title': 'RETURN NULL vs RETURN NEW in BEFORE INSERT Triggers', 'topic': 'Triggers', 'subtopic': 'PL/pgSQL Return Semantics', 'difficulty': 'Easy', 'source': 'GATE CS 2014', 'question_type': 'conceptual', 'prompt': "In a PostgreSQL PL/pgSQL row-level BEFORE INSERT trigger, what is the exact operational effect if the trigger function executes 'RETURN NULL;' versus 'RETURN NEW;'? Does returning NULL cause the database to raise an exception or abort the transaction?", 'starter_code': '-- Effect of RETURN NEW in BEFORE INSERT:\n-- Effect of RETURN NULL in BEFORE INSERT:\n-- Does RETURN NULL raise an error or rollback?', 'solution_key': '1. RETURN NEW: Instructs PostgreSQL to proceed with inserting the candidate row (including any mutations made to the NEW pseudo-record) into the target relation heap.\n2. RETURN NULL: Silently cancels the insertion of the current row. The row is completely skipped and not written to disk, but NO error or exception is raised, and the surrounding transaction does NOT abort.\nReturning NULL is a standard design pattern in BEFORE triggers to conditionally filter or suppress duplicate or invalid tuples without rolling back the entire query batch.', 'ground_truth_explanation': 'In a BEFORE row trigger, returning NULL suppresses the DML operation for that specific tuple without error. Returning NEW allows the engine to persist the tuple.', 'evaluation_rubric': {'key_concepts': ['RETURN NEW proceeds with insertion', 'RETURN NULL cancels/suppresses row insertion', 'No error or exception raised on RETURN NULL', 'Transaction does not abort'], 'common_mistakes': ['Claiming RETURN NULL raises an exception', 'Assuming RETURN NULL rolls back the transaction']}, 'hints': ['Hint 1: What happens in a filter when an item does not pass?', 'Hint 2: Review PostgreSQL PL/pgSQL documentation on Trigger Return Values.']}, {'id': 'EASY-10', 'title': 'WITH GRANT OPTION Fundamentals', 'topic': 'RBAC', 'subtopic': 'Discretionary Delegation', 'difficulty': 'Easy', 'source': 'GATE CS 2011 / Silberschatz Ch 4', 'question_type': 'conceptual', 'prompt': "Explain the purpose of the 'WITH GRANT OPTION' clause in an SQL GRANT statement. What privilege does it bestow upon the recipient, and what restriction exists if a user attempts to pass permissions without this option?", 'starter_code': '-- Purpose of WITH GRANT OPTION:\n-- Privilege bestowed:\n-- Consequence if attempted without this option:', 'solution_key': "The 'WITH GRANT OPTION' clause grants the recipient the authorization to delegate (grant) that specific privilege on the object to other database users or roles.\nIf a user receives a privilege WITHOUT the grant option and attempts to execute a GRANT statement to share that privilege with a third party, PostgreSQL rejects the operation with error 42501 (insufficient_privilege). Only table owners, superusers, or grantees with WITH GRANT OPTION can delegate access.", 'ground_truth_explanation': 'WITH GRANT OPTION creates a delegable edge in the database authorization grant graph, allowing transitive propagation of access privileges.', 'evaluation_rubric': {'key_concepts': ['Enables recipient to grant privilege to others', 'Without it, delegating raises insufficient_privilege error', 'Restricted to specified privilege and object'], 'common_mistakes': ['Assuming WITH GRANT OPTION grants superuser rights', 'Confusing it with role inheritance']}, 'hints': ['Hint 1: Can a user share something they are only allowed to consume?', 'Hint 2: How does SQL prevent regular users from escalating privileges across the company?']}, {'id': 'EASY-11', 'title': 'Trigger vs Stored Procedure Architectural Difference', 'topic': 'Triggers', 'subtopic': 'Execution Paradigm', 'difficulty': 'Easy', 'source': 'ISRO CS / UGC-NET', 'question_type': 'conceptual', 'prompt': 'State three fundamental architectural differences between an SQL Trigger and a Stored Procedure in relational database systems with respect to invocation method, parameter passing, and transaction boundary participation.', 'starter_code': '-- 1. Invocation Method:\n-- 2. Parameters:\n-- 3. Transaction Control:', 'solution_key': '1. Invocation Method: Stored procedures must be explicitly invoked by an application or user via CALL or SELECT. Triggers are invoked implicitly and automatically by the database engine in response to specific DML/DDL events.\n2. Parameters: Stored procedures accept explicit input/output parameters. Triggers cannot take direct user parameters; they receive contextual transition records (NEW/OLD) and execution variables (TG_OP, TG_WHEN) automatically from the engine.\n3. Transaction Boundaries: Stored procedures (in modern PostgreSQL) can manage independent transaction control (COMMIT/ROLLBACK). Triggers always execute strictly within the transaction context of the triggering SQL statement.', 'ground_truth_explanation': 'Triggers are reactive, event-bound rules bound to the caller transaction context; stored procedures are proactive, parameterized program modules.', 'evaluation_rubric': {'key_concepts': ['Triggers invoked implicitly vs procedures explicitly', 'Triggers use transition variables instead of user arguments', 'Triggers run inside parent transaction'], 'common_mistakes': ['Claiming triggers can be called via CALL syntax', 'Believing triggers can commit independently']}, 'hints': ["Hint 1: Do you ever type 'CALL my_trigger()';?", "Hint 2: Can a trigger pass an argument like 'SELECT my_trigger(100)'?"]}, {'id': 'EASY-12', 'title': 'Column-Level SELECT Privilege Syntax', 'topic': 'RBAC', 'subtopic': 'Fine-Grained Authorization', 'difficulty': 'Easy', 'source': 'Silberschatz Database System Concepts', 'question_type': 'coding', 'prompt': "Write SQL to grant role 'financial_analyst' permission to SELECT only the columns 'quarter', 'revenue', and 'profit_margin' from relation 'company_earnings', without granting access to internal columns like 'tax_id' or 'auditor_notes'.", 'starter_code': '-- Grant column-level read access on company_earnings to financial_analyst', 'solution_key': 'GRANT SELECT (quarter, revenue, profit_margin) ON company_earnings TO financial_analyst;', 'ground_truth_explanation': 'SQL-92 and PostgreSQL support column-level discretionary access control by specifying the target column list in parentheses after the SELECT privilege keyword.', 'evaluation_rubric': {'key_concepts': ['GRANT SELECT (cols) ON table TO role', 'Parenthesized column list', 'Excludes unlisted columns'], 'common_mistakes': ['Granting SELECT on entire table', 'Placing column names after table name']}, 'hints': ['Hint 1: Specify the restricted column names immediately after the SELECT keyword.', 'Hint 2: Do not grant table-level SELECT.']}, {'id': 'EASY-13', 'title': 'Transition Variables in DELETE Triggers', 'topic': 'Triggers', 'subtopic': 'Transition Buffers (NEW vs OLD)', 'difficulty': 'Easy', 'source': 'UGC-NET CS 2019', 'question_type': 'conceptual', 'prompt': 'During a row-level DELETE operation in PostgreSQL, what are the states and availability of transition variables NEW and OLD inside the trigger function? Explain why accessing NEW during DELETE causes an error or returns NULL.', 'starter_code': '-- State of OLD during DELETE:\n-- State of NEW during DELETE:\n-- Reason why NEW is invalid during DELETE:', 'solution_key': "1. OLD: Fully populated and accessible. It contains the exact tuple image prior to deletion as read from the relation heap.\n2. NEW: Unassigned / NULL (undefined). In a DELETE operation, the tuple is being removed from the relation; no new prospective row state is being introduced. Therefore, referencing fields of NEW (e.g. NEW.id) in a DELETE trigger causes a runtime error (record 'new' is not yet assigned) or evaluates to NULL.", 'ground_truth_explanation': 'DELETE removes an existing tuple, so only the pre-image (OLD) exists. No candidate replacement row (NEW) is supplied during a deletion.', 'evaluation_rubric': {'key_concepts': ['OLD contains tuple being deleted', 'NEW is NULL/unassigned', 'No prospective row exists for DELETE'], 'common_mistakes': ['Claiming NEW holds default values', 'Assuming NEW holds the deleted row']}, 'hints': ["Hint 1: If an item is deleted, what is its 'new' state in the relation?", 'Hint 2: Contrast this with INSERT, where OLD was undefined.']}, {'id': 'EASY-14', 'title': 'Dropping Triggers with CASCADE vs RESTRICT', 'topic': 'Triggers', 'subtopic': 'DDL Lifecycle Management', 'difficulty': 'Easy', 'source': 'PostgreSQL Certified Professional', 'question_type': 'conceptual', 'prompt': "Explain what happens when a database administrator executes 'DROP TRIGGER trg_audit ON accounts;' versus 'DROP TRIGGER trg_audit ON accounts CASCADE;'. What objects depend on a trigger, and why is RESTRICT the default mode?", 'starter_code': '-- Default DROP TRIGGER behavior (RESTRICT):\n-- DROP TRIGGER ... CASCADE behavior:\n-- Why RESTRICT is standard safety default:', 'solution_key': '1. DROP TRIGGER (RESTRICT): Removes the trigger definition only if no other database objects depend on it. If any dependent objects exist, the command fails with an error. RESTRICT is the default to prevent accidental breakage of schema dependencies.\n2. DROP TRIGGER ... CASCADE: Removes the trigger AND automatically drops any objects that depend on it (such as dependent constraint definitions or cascaded references).\nNote: Dropping a trigger does NOT drop the underlying trigger function; the function remains intact in the schema for reuse.', 'ground_truth_explanation': 'DROP TRIGGER in RESTRICT mode prevents accidental cascading breakage. In CASCADE mode, dependent catalog objects are dropped automatically.', 'evaluation_rubric': {'key_concepts': ['RESTRICT fails if dependencies exist', 'CASCADE drops dependent objects', 'Underlying trigger function is preserved'], 'common_mistakes': ['Assuming DROP TRIGGER deletes the function code', 'Believing CASCADE deletes table rows']}, 'hints': ['Hint 1: In PostgreSQL, is the trigger itself separate from the function it calls?', 'Hint 2: What is the general safety philosophy of RESTRICT across SQL DDL?']}, {'id': 'EASY-15', 'title': 'Role Membership and Group Privilege Inheritance', 'topic': 'RBAC', 'subtopic': 'Inheritance Architecture', 'difficulty': 'Easy', 'source': 'PostgreSQL Catalog / University Masters', 'question_type': 'coding', 'prompt': "Create a group role named 'billing_team' and grant it SELECT and INSERT privileges on 'invoices'. Create an employee role 'bob' that inherits these privileges automatically upon logging in without needing to run 'SET ROLE'.", 'starter_code': '-- 1. Create billing_team\n-- 2. Grant table privileges\n-- 3. Create bob with automatic inheritance', 'solution_key': "CREATE ROLE billing_team NOLOGIN;\nGRANT SELECT, INSERT ON invoices TO billing_team;\nCREATE ROLE bob WITH LOGIN INHERIT IN ROLE billing_team PASSWORD 'BobSecure#2026';", 'ground_truth_explanation': 'Setting INHERIT on a role ensures that all privileges granted to parent group roles are automatically effective during the session without requiring explicit SET ROLE switches.', 'evaluation_rubric': {'key_concepts': ['CREATE ROLE billing_team', 'GRANT SELECT, INSERT ON invoices', 'CREATE ROLE bob WITH LOGIN INHERIT IN ROLE billing_team'], 'common_mistakes': ['Using NOINHERIT requiring manual SET ROLE', 'Forgetting WITH LOGIN for bob']}, 'hints': ['Hint 1: Which keyword allows a role to automatically absorb parent role privileges?', 'Hint 2: Make sure bob has the INHERIT attribute enabled.']}, {'id': 'EASY-16', 'title': 'TG_OP Introspection Variable in PL/pgSQL', 'topic': 'Triggers', 'subtopic': 'Execution Context Introspection', 'difficulty': 'Easy', 'source': 'ISRO Scientist / Engineer', 'question_type': 'coding', 'prompt': "Write a multi-event trigger function 'log_dml_operation()' that inspects the special system variable 'TG_OP'. If the operation is 'INSERT', it prints notice 'OPERATION: INSERT'; if 'UPDATE', notice 'OPERATION: UPDATE'; and if 'DELETE', notice 'OPERATION: DELETE'. Return the appropriate record for each.", 'starter_code': '-- Implement log_dml_operation() inspecting TG_OP', 'solution_key': "CREATE OR REPLACE FUNCTION log_dml_operation()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF TG_OP = 'INSERT' THEN\n        RAISE NOTICE 'OPERATION: INSERT';\n        RETURN NEW;\n    ELSIF TG_OP = 'UPDATE' THEN\n        RAISE NOTICE 'OPERATION: UPDATE';\n        RETURN NEW;\n    ELSIF TG_OP = 'DELETE' THEN\n        RAISE NOTICE 'OPERATION: DELETE';\n        RETURN OLD;\n    END IF;\n    RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;", 'ground_truth_explanation': "TG_OP is a core PL/pgSQL execution context string variable populated with 'INSERT', 'UPDATE', 'DELETE', or 'TRUNCATE', enabling a single trigger function to handle multiple DML event bindings.", 'evaluation_rubric': {'key_concepts': ["Check TG_OP = 'INSERT'", "Check TG_OP = 'UPDATE'", "Check TG_OP = 'DELETE'", 'RETURN NEW on INSERT/UPDATE', 'RETURN OLD on DELETE'], 'common_mistakes': ['Returning NEW on DELETE (causes NULL/error)', 'Comparing TG_OP with lowercase strings']}, 'hints': ['Hint 1: In PostgreSQL, TG_OP returns an uppercase string of the DML command.', 'Hint 2: What record must you return on a DELETE trigger to allow deletion?']}, {'id': 'MED-06', 'title': 'Conditional Trigger Firing via WHEN Clause', 'topic': 'Triggers', 'subtopic': 'Engine Execution Optimization', 'difficulty': 'Medium', 'source': 'GATE CS / Silberschatz Ch 5', 'question_type': 'coding', 'prompt': "Write a CREATE TRIGGER statement on 'customer_accounts' named 'trg_audit_status_change' that executes AFTER UPDATE FOR EACH ROW. The trigger must use an SQL WHEN clause so that the PL/pgSQL function 'record_status_audit()' is invoked ONLY when the 'status' column actually changes (accounting for NULL values).", 'starter_code': '-- CREATE TRIGGER with WHEN clause checking status change', 'solution_key': 'CREATE TRIGGER trg_audit_status_change\nAFTER UPDATE ON customer_accounts\nFOR EACH ROW\nWHEN (OLD.status IS DISTINCT FROM NEW.status)\nEXECUTE FUNCTION record_status_audit();', 'ground_truth_explanation': "The WHEN clause filters trigger execution inside the PostgreSQL core executor before the PL/pgSQL procedural engine is invoked, saving significant CPU overhead. Using 'IS DISTINCT FROM' safely handles NULL status transitions where standard '!=' evaluates to NULL.", 'evaluation_rubric': {'key_concepts': ['WHEN clause in CREATE TRIGGER', 'OLD.status IS DISTINCT FROM NEW.status', 'AFTER UPDATE FOR EACH ROW', 'EXECUTE FUNCTION'], 'common_mistakes': ['Using OLD.status != NEW.status (fails when status is NULL)', 'Evaluating condition inside the function body instead of engine WHEN clause']}, 'hints': ['Hint 1: What SQL operator compares two nullable values safely without evaluating to NULL?', 'Hint 2: Place the WHEN clause between FOR EACH ROW and EXECUTE FUNCTION.']}, {'id': 'MED-07', 'title': 'Multi-User Grant Authorization Graph Cycles', 'topic': 'RBAC', 'subtopic': 'Authorization Graph Traversal', 'difficulty': 'Medium', 'source': 'GATE CS 2017', 'question_type': 'conceptual', 'prompt': "Consider database owner User U0 who grants SELECT WITH GRANT OPTION on table T to User U1. U1 grants SELECT WITH GRANT OPTION to U2. Then U2 grants SELECT WITH GRANT OPTION back to U1. Later, U0 executes: 'REVOKE SELECT ON T FROM U1 CASCADE;'. Analyze the authorization graph reachability: Does U1 or U2 retain the SELECT privilege? Explain why cycles in authorization graphs do not prevent revocation.", 'starter_code': '-- (a) Status of U1 privilege:\n-- (b) Status of U2 privilege:\n-- (c) Authorization graph reachability analysis:', 'solution_key': '(a) U1 loses the privilege (REVOKED).\n(b) U2 loses the privilege (REVOKED).\n(c) In SQL authorization graph theory, privileges are valid only if there exists a directed path from a root authority (the table owner U0) to the user. The edge from U2 back to U1 created a cycle (U1 -> U2 -> U1). When U0 cuts the root edge U0 -> U1 with CASCADE, neither U1 nor U2 has an independent path connecting back to U0. The cycle cannot sustain itself autonomously, and all nodes in the disconnected subgraph are recursively revoked.', 'ground_truth_explanation': 'SQL-92 grant graph semantics mandate rooted DAG reachability. Cycle edges cannot provide independent authorization once the root path from the object owner is severed.', 'evaluation_rubric': {'key_concepts': ['Both U1 and U2 lose privilege', 'Directed path from root owner severed', 'Cycles cannot self-sustain authorization', 'CASCADE prunes unreachable subgraph'], 'common_mistakes': ["Believing U2's grant to U1 keeps U1 alive", 'Claiming cycles cause an infinite loop in the database']}, 'hints': ['Hint 1: Can two people give each other permission to enter a building if the building owner locked them both out?', 'Hint 2: Trace paths from owner U0 to U1 and U2.']}, {'id': 'MED-08', 'title': 'Transition Tables (REFERENCING NEW TABLE AS)', 'topic': 'Triggers', 'subtopic': 'Set-Based Transition Tables', 'difficulty': 'Medium', 'source': 'ANSI SQL:1999 / DB-Book Ch 5', 'question_type': 'coding', 'prompt': "In an AFTER INSERT statement-level trigger on 'employee(emp_id, salary, dept_id)', write the CREATE TRIGGER clause using standard ANSI SQL transition tables (REFERENCING NEW TABLE AS inserted_rows) to pass all newly inserted rows to function 'audit_bulk_hiring()'.", 'starter_code': '-- CREATE TRIGGER statement with REFERENCING NEW TABLE AS', 'solution_key': 'CREATE TRIGGER trg_audit_bulk_hiring\nAFTER INSERT ON employee\nREFERENCING NEW TABLE AS inserted_rows\nFOR EACH STATEMENT\nEXECUTE FUNCTION audit_bulk_hiring();', 'ground_truth_explanation': 'Transition tables (SQL:1999 standard, supported in PostgreSQL 10+) allow statement-level triggers to inspect the entire set of inserted/updated/deleted tuples as a temporary relation (ephemeral named relation), enabling high-performance set-oriented batch processing.', 'evaluation_rubric': {'key_concepts': ['REFERENCING NEW TABLE AS', 'AFTER INSERT ON employee', 'FOR EACH STATEMENT', 'EXECUTE FUNCTION'], 'common_mistakes': ['Using FOR EACH ROW with transition tables', 'Attempting to use NEW/OLD pseudo-records in statement trigger']}, 'hints': ['Hint 1: Use the REFERENCING clause to alias the set of inserted tuples.', 'Hint 2: Transition tables are designed specifically for FOR EACH STATEMENT triggers.']}, {'id': 'MED-09', 'title': 'Trigger Execution Order for Multiple Triggers', 'topic': 'Triggers', 'subtopic': 'Execution Sequence Semantics', 'difficulty': 'Medium', 'source': 'PostgreSQL System Catalog / Stanford CS145', 'question_type': 'conceptual', 'prompt': "If a DBA creates three BEFORE INSERT triggers on table 'orders': 'trg_validate_zip', 'trg_apply_discount', and 'trg_calculate_tax'. (a) In what exact sequence does PostgreSQL execute these triggers? (b) How can an architect guarantee that validation occurs strictly before calculation?", 'starter_code': '-- (a) PostgreSQL default trigger execution order:\n-- (b) How to enforce deterministic execution ordering:', 'solution_key': "(a) In PostgreSQL, when multiple triggers of the same timing (e.g. BEFORE INSERT) exist on the same relation, they are executed in alphabetical order of their trigger names. Thus, the default execution order is: 1. 'trg_apply_discount', 2. 'trg_calculate_tax', 3. 'trg_validate_zip'.\n(b) To guarantee deterministic ordering: architects must either name the triggers with numerical prefixes (e.g., 'trg_01_validate_zip', 'trg_02_apply_discount', 'trg_03_calculate_tax'), or consolidate the logic into a single cohesive trigger function that calls internal routines in the desired explicit sequence.", 'ground_truth_explanation': 'PostgreSQL sorts triggers of the same event by trigger name string collation. Prefixing names or consolidating into one function guarantees deterministic execution.', 'evaluation_rubric': {'key_concepts': ['Alphabetical order by trigger name', 'Calculates sequence correctly', 'Name prefixing (01_, 02_) or single consolidated function'], 'common_mistakes': ['Assuming order of creation defines execution order', 'Assuming triggers fire concurrently']}, 'hints': ['Hint 1: Does PostgreSQL inspect the creation timestamp or the trigger identifier in pg_trigger?', 'Hint 2: Sort the three trigger names alphabetically.']}, {'id': 'MED-10', 'title': 'Session Context Assumption via SET ROLE & RESET ROLE', 'topic': 'RBAC', 'subtopic': 'Dynamic Privilege Assumption', 'difficulty': 'Medium', 'source': 'CMU 15-445', 'question_type': 'coding', 'prompt': "User 'admin_user' is a member of group 'dba_pool'. Write SQL commands for admin_user to: (1) Temporarily switch active privileges to 'dba_pool'; (2) Verify the current active authorization role; (3) Revert back to original login privileges.", 'starter_code': '-- 1. Switch to dba_pool\n-- 2. Inspect current role\n-- 3. Revert to original session user', 'solution_key': 'SET ROLE dba_pool;\nSELECT current_user, session_user;\nRESET ROLE;', 'ground_truth_explanation': "SET ROLE changes the 'current_user' identifier used for permission checking, while preserving 'session_user' as the original authenticated connection. RESET ROLE restores current_user to session_user.", 'evaluation_rubric': {'key_concepts': ['SET ROLE dba_pool', 'SELECT current_user', 'RESET ROLE'], 'common_mistakes': ['Using SET SESSION AUTHORIZATION (which requires superuser)', 'Confusing session_user with current_user']}, 'hints': ['Hint 1: In PostgreSQL, how do you assume a granted group role during a session?', 'Hint 2: How do you return to your original identity?']}, {'id': 'MED-11', 'title': 'Cross-Relation Referential Integrity Enforcement via Triggers', 'topic': 'Triggers', 'subtopic': 'Cross-Table Constraint Enforcement', 'difficulty': 'Medium', 'source': 'Stanford CS145', 'question_type': 'coding', 'prompt': "Write a BEFORE INSERT OR UPDATE trigger function 'enforce_department_manager_limit()' on 'employees(emp_id, name, dept_id, is_manager)'. The system requires that no department can have more than ONE active manager. If inserting or updating an employee with is_manager = TRUE causes the count of managers in that dept_id to exceed 1, raise an exception.", 'starter_code': '-- Function enforce_department_manager_limit()\n-- Validate single manager per department rule', 'solution_key': "CREATE OR REPLACE FUNCTION enforce_department_manager_limit()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_mgr_count INT;\nBEGIN\n    IF NEW.is_manager = TRUE THEN\n        SELECT COUNT(*) INTO v_mgr_count\n        FROM employees\n        WHERE dept_id = NEW.dept_id AND is_manager = TRUE AND emp_id != NEW.emp_id;\n\n        IF v_mgr_count >= 1 THEN\n            RAISE EXCEPTION 'DUPLICATE_MANAGER_VIOLATION: Department % already has an active manager', NEW.dept_id;\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", 'ground_truth_explanation': 'Standard SQL UNIQUE constraints cannot enforce conditional cross-row aggregation without partial indexes. A BEFORE trigger inspects existing relation records and aborts the transaction before violating the business constraint.', 'evaluation_rubric': {'key_concepts': ['BEFORE trigger timing', 'Check NEW.is_manager = TRUE', 'COUNT(*) check excluding current emp_id', 'RAISE EXCEPTION', 'RETURN NEW'], 'common_mistakes': ['Forgetting to exclude NEW.emp_id on UPDATE', 'Using AFTER trigger allowing partial execution']}, 'hints': ['Hint 1: Query the employees table for the count of existing managers in NEW.dept_id.', 'Hint 2: Be sure to exclude the current employee so an UPDATE does not flag itself.']}, {'id': 'MED-12', 'title': 'Revoking EXECUTE on Public Schema Functions', 'topic': 'RBAC', 'subtopic': 'Default Privilege Hardening', 'difficulty': 'Medium', 'source': 'PostgreSQL Enterprise Security', 'question_type': 'coding', 'prompt': "In PostgreSQL, newly created functions grant EXECUTE to the pseudo-role 'PUBLIC' by default. Write SQL commands to: (1) Revoke default EXECUTE on function 'process_wire_transfer(INT, NUMERIC)' from PUBLIC; (2) Grant EXECUTE strictly to role 'bank_teller'.", 'starter_code': '-- 1. Revoke default public execution\n-- 2. Grant to bank_teller only', 'solution_key': 'REVOKE EXECUTE ON FUNCTION process_wire_transfer(INT, NUMERIC) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION process_wire_transfer(INT, NUMERIC) TO bank_teller;', 'ground_truth_explanation': 'By default, PostgreSQL follows SQL standard DAC which grants EXECUTE on newly compiled routines to PUBLIC. Hardening database systems requires revoking EXECUTE from PUBLIC and granting access exclusively to privileged roles.', 'evaluation_rubric': {'key_concepts': ['REVOKE EXECUTE ON FUNCTION ... FROM PUBLIC', 'GRANT EXECUTE ON FUNCTION ... TO bank_teller', 'Specifying parameter signature (INT, NUMERIC)'], 'common_mistakes': ['Omitting argument types in function revocation', 'Believing functions are private by default']}, 'hints': ['Hint 1: In PostgreSQL, you must identify functions with their argument types.', 'Hint 2: Revoke from PUBLIC first, then grant to the authorized role.']}, {'id': 'MED-13', 'title': 'Automatic Timestamp Auditing via BEFORE UPDATE Trigger', 'topic': 'Triggers', 'subtopic': 'Automated Metadata Enrichment', 'difficulty': 'Medium', 'source': 'University Masters Entrance', 'question_type': 'coding', 'prompt': "Write a generic PL/pgSQL trigger function 'stamp_updated_at()' and trigger 'trg_set_updated_at' on table 'customer_profiles'. Every time any row in customer_profiles is updated, the trigger must automatically set NEW.updated_at to CURRENT_TIMESTAMP and guarantee that the client cannot falsify this timestamp.", 'starter_code': '-- 1. Trigger function stamp_updated_at()\n-- 2. Overwrite updated_at with current time\n-- 3. Bind trigger to customer_profiles', 'solution_key': 'CREATE OR REPLACE FUNCTION stamp_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at := CURRENT_TIMESTAMP;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_set_updated_at\nBEFORE UPDATE ON customer_profiles\nFOR EACH ROW\nEXECUTE FUNCTION stamp_updated_at();', 'ground_truth_explanation': 'BEFORE UPDATE row triggers can inspect and overwrite columns in the NEW pseudo-record before writing to the relation heap. By forcibly assigning NEW.updated_at := CURRENT_TIMESTAMP, any client-submitted value is discarded and replaced with true server time.', 'evaluation_rubric': {'key_concepts': ['BEFORE UPDATE timing', 'NEW.updated_at := CURRENT_TIMESTAMP', 'RETURN NEW', 'FOR EACH ROW'], 'common_mistakes': ['Using AFTER UPDATE where NEW is read-only', 'Checking if NEW.updated_at is null instead of unconditionally overwriting']}, 'hints': ['Hint 1: Can an AFTER trigger change what is written to the table?', 'Hint 2: Overwrite NEW.updated_at directly in memory.']}, {'id': 'MED-14', 'title': 'Downstream Revocation under RESTRICT Failure Mode', 'topic': 'RBAC', 'subtopic': 'Revocation Constraint Modes', 'difficulty': 'Medium', 'source': 'GATE CS 2020', 'question_type': 'conceptual', 'prompt': "DBA Alice grants SELECT WITH GRANT OPTION on table 'patient_records' to Bob. Bob grants SELECT to Charlie. Alice executes: 'REVOKE SELECT ON patient_records FROM Bob RESTRICT;'. (a) What is the immediate result of Alice's query? (b) Does Bob keep his privilege? (c) Does Charlie keep his privilege? (d) How should Alice formulate the query to revoke both?", 'starter_code': "-- (a) Result of Alice's REVOKE RESTRICT command:\n-- (b) Bob's privilege state:\n-- (c) Charlie's privilege state:\n-- (d) Correct query to revoke both:", 'solution_key': "(a) The command FAILS and raises an ERROR (PostgreSQL error 2BP01: dependent objects still exist).\n(b) Bob keeps his privilege.\n(c) Charlie keeps his privilege.\n(d) Alice must execute: 'REVOKE SELECT ON patient_records FROM Bob CASCADE;'.\nExplanation: Under RESTRICT mode, the database guarantees that if any dependent downstream grants exist, the revocation is aborted completely without modifying any authorization states.", 'ground_truth_explanation': 'RESTRICT preserves referential integrity across the authorization grant graph by rejecting any command that would produce orphaned dependent grants.', 'evaluation_rubric': {'key_concepts': ['Command aborts with error', 'Bob retains privilege', 'Charlie retains privilege', 'CASCADE required to succeed'], 'common_mistakes': ['Assuming Bob loses privilege while Charlie keeps it', 'Thinking RESTRICT silently ignores Charlie']}, 'hints': ['Hint 1: What does RESTRICT mean when dropping a table with foreign keys?', 'Hint 2: Under RESTRICT, the engine will refuse to execute if dependencies exist.']}, {'id': 'MED-15', 'title': 'Maker-Checker Segregation of Duties (SoD) Trigger', 'topic': 'Hybrid Security', 'subtopic': 'Procedural Authorization Checks', 'difficulty': 'Medium', 'source': 'Core Banking Architecture', 'question_type': 'coding', 'prompt': "Implement a PL/pgSQL trigger function 'enforce_maker_checker()' on 'payment_orders(order_id, created_by, approved_by, status)'. When status is updated to 'APPROVED', the trigger must verify: (1) The user executing the update (session_user) is NOT the same user who created the order (created_by); (2) Store session_user into approved_by. If created_by equals session_user, abort with 'MAKER_CANNOT_APPROVE'.", 'starter_code': '-- 1. Trigger function enforce_maker_checker()\n-- 2. Verify session_user != created_by\n-- 3. Set approved_by := session_user', 'solution_key': "CREATE OR REPLACE FUNCTION enforce_maker_checker()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.status = 'APPROVED' AND OLD.status != 'APPROVED' THEN\n        IF OLD.created_by = session_user THEN\n            RAISE EXCEPTION 'MAKER_CANNOT_APPROVE: Order creator (%) cannot approve own payment', session_user;\n        END IF;\n        NEW.approved_by := session_user;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", 'ground_truth_explanation': 'Segregation of Duties (SoD) prevents fraud by enforcing that a maker cannot check their own transactions. Evaluating session_user within a BEFORE UPDATE trigger binds authentication directly to business validation.', 'evaluation_rubric': {'key_concepts': ['BEFORE UPDATE timing', 'Check OLD.created_by = session_user', 'RAISE EXCEPTION on equality', 'NEW.approved_by := session_user', 'RETURN NEW'], 'common_mistakes': ['Using AFTER UPDATE', 'Comparing NEW.created_by instead of OLD.created_by']}, 'hints': ["Hint 1: In PostgreSQL, 'session_user' returns the authenticated database account.", 'Hint 2: Compare OLD.created_by with session_user before setting NEW.approved_by.']}, {'id': 'MED-16', 'title': 'View Ownership Chaining vs Table Authorization', 'topic': 'RBAC', 'subtopic': 'Ownership Chaining & Abstraction', 'difficulty': 'Medium', 'source': 'UC Berkeley CS186', 'question_type': 'conceptual', 'prompt': "DBA Alice owns table 'salaries(emp_id, amount)'. Alice creates a view 'public_salary_view' showing average salary per department and grants SELECT on this view to role 'analyst'. Role 'analyst' has NO permission on the underlying 'salaries' table. (a) Can 'analyst' query 'public_salary_view'? (b) Explain the concept of 'Ownership Chaining' and its security implications.", 'starter_code': '-- (a) Can analyst query public_salary_view?\n-- (b) Explanation of Ownership Chaining:', 'solution_key': "(a) Yes, 'analyst' can successfully query 'public_salary_view'.\n(b) Ownership Chaining: In PostgreSQL and relational databases, when a view and its underlying base tables are owned by the same user (Alice), the engine bypasses permission checks on the underlying tables when accessed through the view. The engine checks permissions ONLY on the top-level view. This allows administrators to expose controlled aggregations and row subsets without exposing raw underlying sensitive tables.", 'ground_truth_explanation': 'Ownership chaining allows secure schema abstraction. When view owner matches table owner, indirect access succeeds without granting direct table privileges.', 'evaluation_rubric': {'key_concepts': ['Analyst can query view successfully', 'Permission checks bypassed on base table', 'View owner matches table owner', 'Enables secure data encapsulation'], 'common_mistakes': ['Assuming analyst needs SELECT on base table', 'Believing views require superuser']}, 'hints': ['Hint 1: Who created both the view and the underlying table?', 'Hint 2: Do views exist to provide secure access abstractions?']}, {'id': 'HARD-06', 'title': 'Mutating Relation with DEFERRABLE INITIALLY DEFERRED', 'topic': 'Triggers', 'subtopic': 'Deferred Constraint Triggers', 'difficulty': 'Hard', 'source': 'GATE CS Advanced / PostgreSQL Docs', 'question_type': 'coding', 'prompt': "In a mutual circular relationship between 'department(dept_id, manager_id)' and 'employee(emp_id, dept_id)', an immediate trigger checking foreign references fails during transaction execution. Write a CREATE CONSTRAINT TRIGGER statement named 'trg_check_mutual_fk' that defers evaluation until the transaction COMMIT stage.", 'starter_code': '-- CREATE CONSTRAINT TRIGGER with DEFERRABLE INITIALLY DEFERRED', 'solution_key': 'CREATE CONSTRAINT TRIGGER trg_check_mutual_fk\nAFTER INSERT OR UPDATE ON department\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW\nEXECUTE FUNCTION verify_mutual_foreign_key();', 'ground_truth_explanation': 'Constraint triggers created with DEFERRABLE INITIALLY DEFERRED postpone trigger firing until the end of the transaction (COMMIT), allowing mutually dependent circular records to be inserted in separate intermediate statements without violating integrity constraints.', 'evaluation_rubric': {'key_concepts': ['CREATE CONSTRAINT TRIGGER', 'AFTER timing', 'DEFERRABLE INITIALLY DEFERRED', 'Fires at transaction COMMIT'], 'common_mistakes': ['Using BEFORE timing on constraint trigger (invalid in SQL)', 'Forgetting DEFERRABLE keyword']}, 'hints': ['Hint 1: Constraint triggers in PostgreSQL must always be AFTER triggers.', 'Hint 2: Use DEFERRABLE INITIALLY DEFERRED to postpone execution until COMMIT.']}, {'id': 'HARD-07', 'title': 'Recursive Trigger Cascades and pg_trigger_depth() Guard', 'topic': 'Triggers', 'subtopic': 'Re-entrancy & Recursion Limits', 'difficulty': 'Hard', 'source': 'CMU 15-445', 'question_type': 'coding', 'prompt': "An AFTER UPDATE trigger on 'nodes(id, parent_id, weight)' re-computes aggregate weights by updating parent nodes in the same table, risking infinite recursion. Implement a PL/pgSQL guard using 'pg_trigger_depth()' to prevent the trigger from executing if the recursion nesting depth exceeds 10.", 'starter_code': '-- Guard recursion depth with pg_trigger_depth()', 'solution_key': "CREATE OR REPLACE FUNCTION cascade_node_weight()\nRETURNS TRIGGER AS $$\nBEGIN\n    -- Guard against unbounded recursive trigger cascades\n    IF pg_trigger_depth() > 10 THEN\n        RAISE EXCEPTION 'RECURSION_DEPTH_EXCEEDED: Trigger cascade nested depth % exceeds safety limit of 10',\n            pg_trigger_depth();\n    END IF;\n\n    UPDATE nodes\n    SET weight = weight + (NEW.weight - OLD.weight)\n    WHERE id = NEW.parent_id;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", 'ground_truth_explanation': "pg_trigger_depth() tracks the current call stack nesting depth of triggers. Inspecting this function inside self-referencing triggers halts runaway recursive cascades before exhausting PostgreSQL's max_stack_depth.", 'evaluation_rubric': {'key_concepts': ['pg_trigger_depth() check', 'Check depth > 10', 'RAISE EXCEPTION', 'UPDATE parent node', 'RETURN NEW'], 'common_mistakes': ['Using a static integer variable (reset on every invocation)', 'Allowing infinite loop until crash']}, 'hints': ['Hint 1: Which built-in PostgreSQL function returns the integer nesting level of trigger invocations?', 'Hint 2: Check pg_trigger_depth() at the start of the function body.']}, {'id': 'HARD-08', 'title': 'INSTEAD OF Trigger on Group-By Aggregate Views', 'topic': 'Triggers', 'subtopic': 'Non-Updatable View Decomposition', 'difficulty': 'Hard', 'source': 'UC Berkeley CS186', 'question_type': 'coding', 'prompt': "Given base table 'order_items(item_id, order_id, product_name, price)' and aggregate view 'order_totals_view(order_id, item_count, total_price)' defined via GROUP BY order_id. Write an INSTEAD OF DELETE trigger on the view so that when a user deletes from 'order_totals_view WHERE order_id = 101', all corresponding items in 'order_items' are deleted.", 'starter_code': '-- 1. Trigger function delete_from_order_totals()\n-- 2. Delete underlying items from order_items\n-- 3. Bind INSTEAD OF DELETE to view', 'solution_key': 'CREATE OR REPLACE FUNCTION delete_from_order_totals()\nRETURNS TRIGGER AS $$\nBEGIN\n    DELETE FROM order_items\n    WHERE order_id = OLD.order_id;\n    RETURN OLD;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_instead_of_delete_totals\nINSTEAD OF DELETE ON order_totals_view\nFOR EACH ROW\nEXECUTE FUNCTION delete_from_order_totals();', 'ground_truth_explanation': 'Aggregate views with GROUP BY cannot be modified natively. An INSTEAD OF trigger intercepts DML on the view and dispatches appropriate deletions to normalized base tables.', 'evaluation_rubric': {'key_concepts': ['INSTEAD OF DELETE ON view', 'DELETE FROM order_items WHERE order_id = OLD.order_id', 'RETURN OLD', 'FOR EACH ROW'], 'common_mistakes': ['Attempting to delete directly from the view in the function', 'Using BEFORE/AFTER trigger on a view']}, 'hints': ['Hint 1: Which transition variable holds the record being deleted from the view?', "Hint 2: Issue a DELETE against base table 'order_items' matching OLD.order_id."]}, {'id': 'HARD-09', 'title': 'Trojan-Horse Defense: Securing search_path in SECURITY DEFINER', 'topic': 'Hybrid Security', 'subtopic': 'Privilege Escalation Mitigation', 'difficulty': 'Hard', 'source': 'PostgreSQL Security Advisories', 'question_type': 'coding', 'prompt': "A SECURITY DEFINER trigger function executes with elevated superuser privileges. If an unprivileged user creates a malicious schema 'public' table or function, they can hijack superuser execution via search_path poisoning. Write a secure PL/pgSQL function header that prevents search_path privilege escalation attacks.", 'starter_code': '-- Define function with SECURITY DEFINER and secure search_path', 'solution_key': 'CREATE OR REPLACE FUNCTION secure_elevated_audit()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = pg_catalog, pg_temp\nLANGUAGE plpgsql AS $$\nBEGIN\n    -- Secure execution body\n    RETURN NEW;\nEND;\n$$;', 'ground_truth_explanation': "In PostgreSQL, a SECURITY DEFINER function executes in the context of the function creator. If search_path is mutable, an attacker can manipulate search_path to resolve unqualified object names to malicious tables. Explicitly setting 'SET search_path = pg_catalog, pg_temp' neutralizes this vulnerability.", 'evaluation_rubric': {'key_concepts': ['SECURITY DEFINER clause', 'SET search_path = pg_catalog, pg_temp', 'Explicit search_path pinning', 'Mitigates privilege escalation'], 'common_mistakes': ['Omitting SET search_path clause', 'Including user-writable public schema in search_path']}, 'hints': ['Hint 1: How can you pin the function search_path in the CREATE FUNCTION declaration?', 'Hint 2: Specify only trusted system schemas (pg_catalog, pg_temp).']}, {'id': 'HARD-10', 'title': 'Pre-RLS Multi-Tenant Isolation via BEFORE INSERT Trigger', 'topic': 'Hybrid Security', 'subtopic': 'Tenant Boundary Enforcement', 'difficulty': 'Hard', 'source': 'CMU 15-445', 'question_type': 'coding', 'prompt': "In a multi-tenant database before native Row Level Security (RLS) was available, architects enforced data isolation via triggers. Write a BEFORE INSERT trigger function 'enforce_tenant_isolation()' on 'tenant_records(record_id, tenant_id, data)'. The function must extract the active tenant ID from a session configuration variable 'current_setting('app.current_tenant_id')' and force NEW.tenant_id to this value, preventing any tenant from spoofing foreign IDs.", 'starter_code': '-- 1. Read app.current_tenant_id via current_setting()\n-- 2. Force NEW.tenant_id to authenticated tenant\n-- 3. BEFORE INSERT trigger binding', 'solution_key': "CREATE OR REPLACE FUNCTION enforce_tenant_isolation()\nRETURNS TRIGGER AS $$\nDECLARE\n    v_tenant_id INT;\nBEGIN\n    v_tenant_id := current_setting('app.current_tenant_id')::INT;\n    IF v_tenant_id IS NULL THEN\n        RAISE EXCEPTION 'TENANT_CONTEXT_MISSING: Operation aborted due to missing tenant session variable';\n    END IF;\n    -- Forcibly overwrite client-supplied tenant_id\n    NEW.tenant_id := v_tenant_id;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_tenant_isolation\nBEFORE INSERT ON tenant_records\nFOR EACH ROW\nEXECUTE FUNCTION enforce_tenant_isolation();", 'ground_truth_explanation': 'By reading current_setting() and forcibly overriding NEW.tenant_id in a BEFORE INSERT trigger, client-submitted tenant IDs are disregarded and replaced with the authenticated session context.', 'evaluation_rubric': {'key_concepts': ["current_setting('app.current_tenant_id')", 'NEW.tenant_id := v_tenant_id', 'BEFORE INSERT timing', 'FOR EACH ROW'], 'common_mistakes': ['Using AFTER INSERT allowing wrong ID persistence', 'Failing to check for missing session setting']}, 'hints': ["Hint 1: Use current_setting('variable_name') to read session-level context.", 'Hint 2: Overwrite NEW.tenant_id before the record is persisted to disk.']}, {'id': 'HARD-11', 'title': 'DDL Event Triggers (ON ddl_command_end) for Schema Tampering', 'topic': 'Hybrid Security', 'subtopic': 'Event Triggers & Schema Hardening', 'difficulty': 'Hard', 'source': 'Enterprise DBA / Stanford', 'question_type': 'coding', 'prompt': "PostgreSQL provides Event Triggers to intercept DDL commands. Write a DDL event trigger 'trg_prevent_drop_table' that executes 'ON sql_drop'. If a user attempts to drop any table whose schema is 'production', abort the operation with exception 'PRODUCTION_DROPS_PROHIBITED'.", 'starter_code': "-- 1. Event trigger function checking pg_event_trigger_dropped_objects()\n-- 2. Block drops in 'production' schema\n-- 3. CREATE EVENT TRIGGER trg_prevent_drop_table ON sql_drop", 'solution_key': "CREATE OR REPLACE FUNCTION block_production_drops()\nRETURNS EVENT_TRIGGER AS $$\nDECLARE\n    obj RECORD;\nBEGIN\n    FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP\n        IF obj.schema_name = 'production' AND obj.object_type = 'table' THEN\n            RAISE EXCEPTION 'PRODUCTION_DROPS_PROHIBITED: Dropping table % in production schema is strictly forbidden.',\n                obj.object_identity;\n        END IF;\n    END LOOP;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER trg_prevent_drop_table\nON sql_drop\nEXECUTE FUNCTION block_production_drops();", 'ground_truth_explanation': "Event triggers capture global DDL events. Using 'ON sql_drop' and querying 'pg_event_trigger_dropped_objects()' allows schema administrators to inspect and abort destructive commands before execution completes.", 'evaluation_rubric': {'key_concepts': ['RETURNS EVENT_TRIGGER', 'pg_event_trigger_dropped_objects()', "Check obj.schema_name = 'production'", 'CREATE EVENT TRIGGER ... ON sql_drop'], 'common_mistakes': ['Attempting to use a standard table trigger for DDL', 'Using BEFORE DROP syntax (invalid in PostgreSQL)']}, 'hints': ['Hint 1: Standard triggers cannot intercept DROP TABLE; an EVENT TRIGGER is required.', "Hint 2: Use pg_event_trigger_dropped_objects() inside an 'ON sql_drop' event trigger."]}, {'id': 'HARD-12', 'title': 'ACID Savepoints and Exception Handling inside Triggers', 'topic': 'Triggers', 'subtopic': 'Subtransaction Exception Handling', 'difficulty': 'Hard', 'source': 'PostgreSQL Internals / GATE CS', 'question_type': 'conceptual', 'prompt': "In PL/pgSQL, a trigger function contains a block: 'BEGIN ... INSERT INTO log ... EXCEPTION WHEN unique_violation THEN ... END;'. (a) How does PostgreSQL physically implement this exception block under the hood? (b) What is the performance cost of an exception block inside high-frequency row-level triggers?", 'starter_code': '-- (a) Underlying implementation mechanism of exception block:\n-- (b) Performance implications on high-frequency triggers:', 'solution_key': '(a) Under the hood, PostgreSQL implements every BEGIN ... EXCEPTION block by creating an internal transactional SAVEPOINT (subtransaction). When an exception occurs, the engine rolls back to the savepoint and continues execution.\n(b) Performance Cost: Creating and tearing down internal savepoints for every row in a high-frequency trigger carries significant CPU and transaction ID (XID) overhead. It consumes subtransaction locks and causes cache thrashing in pg_subtrans, degrading bulk write throughput. Exception blocks should be avoided in tight row loops.', 'ground_truth_explanation': 'PL/pgSQL exception blocks establish internal subtransactions via savepoints. In high-frequency row triggers, subtransaction allocation generates substantial performance degradation.', 'evaluation_rubric': {'key_concepts': ['Implemented via internal SAVEPOINT / subtransaction', 'Rollback to savepoint on exception', 'High CPU and XID allocation overhead', 'pg_subtrans lock contention in high-frequency triggers'], 'common_mistakes': ['Assuming exceptions do not affect performance', 'Believing exception blocks spawn independent threads']}, 'hints': ['Hint 1: How can a database roll back part of a block without aborting the whole transaction?', 'Hint 2: What transaction primitive enables partial rollback?']}, {'id': 'HARD-13', 'title': 'Dynamic Row-Level Security Policies vs Trigger Guards', 'topic': 'RBAC', 'subtopic': 'Engine-Level RLS Integration', 'difficulty': 'Hard', 'source': 'CMU 15-445', 'question_type': 'coding', 'prompt': "Contrast Row Level Security (RLS) with BEFORE triggers. Write SQL to enable Row Level Security on table 'account_ledgers' and define a policy 'teller_branch_policy' on SELECT so that users with role 'teller' can only see records where 'branch_id = current_setting('app.current_branch')::INT'.", 'starter_code': '-- 1. Enable RLS on account_ledgers\n-- 2. CREATE POLICY for role teller', 'solution_key': "ALTER TABLE account_ledgers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY teller_branch_policy ON account_ledgers\nFOR SELECT\nTO teller\nUSING (branch_id = current_setting('app.current_branch')::INT);", 'ground_truth_explanation': 'Row Level Security (RLS) injects security filter predicates directly into the query tree during query rewrite, avoiding the per-row procedural interpretation overhead of triggers and guaranteeing invisibility across SELECT queries.', 'evaluation_rubric': {'key_concepts': ['ALTER TABLE account_ledgers ENABLE ROW LEVEL SECURITY', 'CREATE POLICY ... FOR SELECT', 'TO teller', 'USING clause with session branch check'], 'common_mistakes': ['Using WITH CHECK for SELECT policy (WITH CHECK is for INSERT/UPDATE)', 'Forgetting to enable RLS on table']}, 'hints': ['Hint 1: First enable RLS on the table with ALTER TABLE.', 'Hint 2: Use the USING clause to filter visibility for SELECT operations.']}, {'id': 'HARD-14', 'title': 'Multi-Branch Cyclic Grant Graph Traversal', 'topic': 'RBAC', 'subtopic': 'Graph-Theoretic Access Revocation', 'difficulty': 'Hard', 'source': 'GATE CS 2022', 'question_type': 'conceptual', 'prompt': "Owner U0 grants SELECT WITH GRANT OPTION to U1 and U2 independently. U1 grants SELECT to U3. U2 ALSO grants SELECT to U3. Later, U0 executes: 'REVOKE SELECT ON table FROM U1 CASCADE;'. Analyze whether U3 retains the SELECT privilege and explain the DAG reachability algorithm.", 'starter_code': '-- Status of U3 privilege:\n-- DAG reachability explanation:', 'solution_key': 'U3 RETAINS the SELECT privilege.\nExplanation: The DBMS constructs a directed authorization grant graph with edges: U0 -> U1 -> U3 and U0 -> U2 -> U3. When U0 revokes U1 with CASCADE, the edge U0 -> U1 and the dependent edge U1 -> U3 are pruned.\nHowever, the DBMS evaluates reachability from the root owner (U0). Because U3 still possesses an independent, unrevoked path from the owner via U2 (U0 -> U2 -> U3), U3 remains reachable and active in the authorization graph. Only privileges that lose all root connections are revoked.', 'ground_truth_explanation': 'SQL authorization revocation executes a topological reachability traversal. If a node maintains an alternative path to the object owner, its privilege survives.', 'evaluation_rubric': {'key_concepts': ['U3 retains privilege', 'Alternative independent path via U2', 'Topological reachability from owner U0', 'Only edges derived solely from U1 are pruned'], 'common_mistakes': ['Assuming U3 loses privilege completely', 'Claiming CASCADE revokes all users on the table']}, 'hints': ['Hint 1: Trace all directed paths from U0 to U3.', 'Hint 2: Did U2 receive its privilege from U1 or directly from U0?']}, {'id': 'HARD-15', 'title': 'Trigger Overhead and Statement Batching on Bulk Ingestion', 'topic': 'Triggers', 'subtopic': 'Performance & Architecture', 'difficulty': 'Hard', 'source': 'CMU 15-445', 'question_type': 'conceptual', 'prompt': "A data engineering pipeline loads 10,000,000 rows into 'market_trades' using PostgreSQL COPY. If an AFTER INSERT FOR EACH ROW trigger is active, explain the physical engine bottlenecks that occur. Compare this against batching with a statement-level trigger using transition tables.", 'starter_code': '-- Row-level trigger bottlenecks during COPY:\n-- Architectural advantage of statement-level transition tables:', 'solution_key': '1. Row-Level Trigger Bottlenecks: For each of the 10,000,000 rows, PostgreSQL must allocate memory context, initialize the PL/pgSQL interpreter, construct NEW pseudo-records, serialize write-ahead logging (WAL), and context-switch between C and procedural execution. This transforms a sequential bulk I/O operation into 10 million procedural function calls, decreasing ingestion throughput by 20x to 100x.\n2. Statement-Level Transition Table Advantage: With an AFTER INSERT FOR EACH STATEMENT trigger with REFERENCING NEW TABLE, PostgreSQL streams all 10M rows in bulk at native hardware speed into a temporary tuplestore, executing the trigger function exactly ONCE at the end of the batch. This allows vectorization and set-based relational operations with minimal procedural overhead.', 'ground_truth_explanation': 'Row triggers incur per-tuple procedural interpreter context switches. Statement triggers with transition tables amortize execution across the entire batch.', 'evaluation_rubric': {'key_concepts': ['Row triggers cause 10M interpreter context switches', 'Disrupts sequential bulk I/O', 'Statement triggers fire once for entire batch', 'Set-based vector processing via transition tables'], 'common_mistakes': ['Assuming row triggers execute in parallel', 'Claiming COPY disables triggers automatically']}, 'hints': ['Hint 1: How many times does the PL/pgSQL engine context-switch for 10 million rows?', 'Hint 2: How does set-oriented SQL differ from row-by-row procedural loops?']}, {'id': 'HARD-16', 'title': 'Dual-Key Multi-Role Transaction Approval State Machine', 'topic': 'Hybrid Security', 'subtopic': 'State Transition Security Guards', 'difficulty': 'Hard', 'source': 'Core Banking / SOX Compliance', 'question_type': 'coding', 'prompt': "Design a high-security PL/pgSQL trigger function 'guard_high_value_wire()' on 'wire_transfers(transfer_id, amount, status, initiator_role, approver_role)'. For transfers exceeding $1,000,000, transitioning status from 'PENDING' to 'SETTLED' requires: (1) The user must belong to role 'executive_board'; (2) OLD.initiator_role cannot be 'executive_board' (enforcing two distinct role tiers); (3) Any violation raises 'DUAL_CONTROL_VIOLATION'.", 'starter_code': '-- 1. Trigger function guard_high_value_wire()\n-- 2. Verify amount > 1000000 requires dual control\n-- 3. Enforce executive_board membership and role separation', 'solution_key': "CREATE OR REPLACE FUNCTION guard_high_value_wire()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.status = 'SETTLED' AND OLD.status = 'PENDING' AND OLD.amount > 1000000 THEN\n        -- Enforce Dual Control: Approver must belong to executive_board\n        IF NOT pg_has_role(session_user, 'executive_board', 'MEMBER') THEN\n            RAISE EXCEPTION 'DUAL_CONTROL_VIOLATION: Approving wires > $1M requires executive_board membership (Caller: %)',\n                session_user;\n        END IF;\n\n        -- Enforce Segregation of Duties across role tiers\n        IF OLD.initiator_role = 'executive_board' THEN\n            RAISE EXCEPTION 'DUAL_CONTROL_VIOLATION: Executive role cannot both initiate and settle the same high-value wire';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", 'ground_truth_explanation': 'Dual-control state machines protect critical financial assets by programmatically validating caller role memberships via pg_has_role() and verifying segregation of duties before allowing irreversible status transitions.', 'evaluation_rubric': {'key_concepts': ["Check NEW.status = 'SETTLED' and OLD.amount > 1000000", "pg_has_role(session_user, 'executive_board', 'MEMBER')", "Check OLD.initiator_role != 'executive_board'", 'RAISE EXCEPTION', 'RETURN NEW'], 'common_mistakes': ['Using AFTER trigger allowing settlement commit', 'Comparing strings instead of checking role membership via pg_has_role']}, 'hints': ["Hint 1: Use pg_has_role(user, role, 'MEMBER') to verify role hierarchy membership.", 'Hint 2: Enforce that OLD.initiator_role is not from the same executive tier.']}]
